"""
    Returns a list of the product of each element in the first list
    with each element in the second list shifted by one index.
    """
def get_shifted_product(first_list: list, second_list: list) -> list {
    shifted_second_list = second_list[1:];
    return [(a * b) for (a, b) in zip(first_list, shifted_second_list)];
}

"""
    This function determines any applicable experience boost.
    Assumes abilities is a list of tuples (ability as str, stat as int)
    Assumes prime_ability is a string.
    Returns a percentage as a str.
    """
def experience_boost_determination(ability_scores: Any, prime_ability: Any) -> object {
    abilities = [
        'Strength',
        'Intelligence',
        'Wisdom',
        'Dexterity',
        'Constitution',
        'Charisma'
    ];
    stats = ability_scores;
    prime = abilities.index(prime_ability);
    if ((stats[prime][1] == 13) or (stats[prime][1] == 14)) {
        experience_boost = '5%';
    } elif (stats[prime][1] >= 15) {
        experience_boost = '10%';
    } else {
        experience_boost = '0%';
    }
    return experience_boost;
}

